-- READ-ONLY exact source/target comparison at both gap boundaries; 25 source-present 2019-2020 gaps.
WITH gaps AS (SELECT '2019:1558259700:1558341000' gap_id,1558259700 left_time,1558341000 right_time UNION ALL SELECT '2019:1559203200:1559208900' gap_id,1559203200 left_time,1559208900 right_time UNION ALL SELECT '2019:1559209500:1559213700' gap_id,1559209500 left_time,1559213700 right_time UNION ALL SELECT '2019:1559219100:1559223300' gap_id,1559219100 left_time,1559223300 right_time UNION ALL SELECT '2019:1572134100:1572138000' gap_id,1572134100 left_time,1572138000 right_time UNION ALL SELECT '2020:1582104300:1582122300' gap_id,1582104300 left_time,1582122300 right_time UNION ALL SELECT '2020:1582401000:1582404900' gap_id,1582401000 left_time,1582404900 right_time UNION ALL SELECT '2020:1582604400:1582613100' gap_id,1582604400 left_time,1582613100 right_time UNION ALL SELECT '2020:1582666200:1582680000' gap_id,1582666200 left_time,1582680000 right_time UNION ALL SELECT '2020:1583030400:1583038800' gap_id,1583030400 left_time,1583038800 right_time UNION ALL SELECT '2020:1583044200:1583069100' gap_id,1583044200 left_time,1583069100 right_time UNION ALL SELECT '2020:1583069100:1583089800' gap_id,1583069100 left_time,1583089800 right_time UNION ALL SELECT '2020:1583110200:1583117400' gap_id,1583110200 left_time,1583117400 right_time UNION ALL SELECT '2020:1583125800:1583140800' gap_id,1583125800 left_time,1583140800 right_time UNION ALL SELECT '2020:1583158800:1583166600' gap_id,1583158800 left_time,1583166600 right_time UNION ALL SELECT '2020:1589369100:1589372700' gap_id,1589369100 left_time,1589372700 right_time UNION ALL SELECT '2020:1589378700:1589384400' gap_id,1589378700 left_time,1589384400 right_time UNION ALL SELECT '2020:1589387400:1589402100' gap_id,1589387400 left_time,1589402100 right_time UNION ALL SELECT '2020:1589411100:1589414700' gap_id,1589411100 left_time,1589414700 right_time UNION ALL SELECT '2020:1590039600:1590063600' gap_id,1590039600 left_time,1590063600 right_time UNION ALL SELECT '2020:1590086100:1590090000' gap_id,1590086100 left_time,1590090000 right_time UNION ALL SELECT '2020:1592803800:1592827800' gap_id,1592803800 left_time,1592827800 right_time UNION ALL SELECT '2020:1592890500:1592915400' gap_id,1592890500 left_time,1592915400 right_time UNION ALL SELECT '2020:1593612000:1593617100' gap_id,1593612000 left_time,1593617100 right_time UNION ALL SELECT '2020:1595488200:1595493000' gap_id,1595488200 left_time,1595493000 right_time)
SELECT g.gap_id, g.left_time, g.right_time, left_target.outTemp left_target_outTemp, left_target.usUnits left_target_usUnits, left_target.`interval` left_target_interval, (SELECT COUNT(*) FROM loucka_reconstruction.reconstruction_changes h WHERE h.target_time=g.left_time) left_target_history_events, left_old.outTemp left_old_outTemp, left_old.usUnits left_old_usUnits, left_old.`interval` left_old_interval, left_wh.outTemp left_wh_outTemp, left_wh.usUnits left_wh_usUnits, left_wh.`interval` left_wh_interval, right_target.outTemp right_target_outTemp, right_target.usUnits right_target_usUnits, right_target.`interval` right_target_interval, (SELECT COUNT(*) FROM loucka_reconstruction.reconstruction_changes h WHERE h.target_time=g.right_time) right_target_history_events, right_old.outTemp right_old_outTemp, right_old.usUnits right_old_usUnits, right_old.`interval` right_old_interval, right_wh.outTemp right_wh_outTemp, right_wh.usUnits right_wh_usUnits, right_wh.`interval` right_wh_interval
FROM gaps g LEFT JOIN `loucka_reconstruction`.archive left_target ON left_target.dateTime=g.left_time LEFT JOIN `old_weewx`.archive left_old ON left_old.dateTime=g.left_time LEFT JOIN `weewx_WH1080`.archive left_wh ON left_wh.dateTime=g.left_time LEFT JOIN `loucka_reconstruction`.archive right_target ON right_target.dateTime=g.right_time LEFT JOIN `old_weewx`.archive right_old ON right_old.dateTime=g.right_time LEFT JOIN `weewx_WH1080`.archive right_wh ON right_wh.dateTime=g.right_time ORDER BY g.left_time;
